query Search {
  search(query:"hello world", version: "6.7.2", first: 48) {
    id
    unicode
    svgs(filter: { familyStyles: [
      { family: SHARP, style: SOLID }
      { family: CLASSIC, style: BRANDS }
    ] }) {
      html
      familyStyle{
        prefix
      }
    }
  }
}

